"""Genera el informe de hallazgos confirmados; no contiene funciones de escritura remota."""
from pathlib import Path
import json,re,html,csv,unicodedata,collections
root=Path(__file__).resolve().parent
load=lambda f:json.loads((root/f).read_text(encoding='utf8'))
articles=load('supabase-articulos.json');laws=load('supabase-leyes.json');sources=load('fuentes.json');auto=load('analisis-automatico.json');checked=load('cotejo.json')
byid={a['id']:a for a in articles}
def norm(s):return re.sub('[^a-z0-9]','',unicodedata.normalize('NFD',s.lower()))
def excerpt(text,needle=''):
    chars=[];positions=[]
    for i,c in enumerate(text):
        for k in norm(c):chars.append(k);positions.append(i)
    at=''.join(chars).find(norm(needle)[:45]) if needle else -1
    if at>=0:
        p=positions[at];return ('…' if p>100 else '')+text[max(0,p-100):p+750]+('…' if p+750<len(text) else '')
    return text if len(text)<900 else text[:600]+'\n[…]\n'+text[-230:]
